// Composes the current zone's whole floor plan into ONE texture: ground, drop shadows, walls /
// cover / doors / props, damage cracks and elevation shading, all baked per pixel from the 16x16
// terrain atlas (Resources/Sprites/terrain_atlas.bytes + terrain_names.txt, generated by
// ArtSource/make_terrain_tiles.py). One sprite for the whole map instead of thousands of tile
// GameObjects; when a tile changes (door opened, cover shot to rubble) only its neighbourhood is
// recomposed (TacticalGridView drains TerrainMap.DirtyTiles).
// The atlas ships as a .bytes TextAsset + Texture2D.LoadImage so it is always CPU-readable,
// whatever the texture importer says. No atlas = flat-colour fallback, same as before the art.
using System.Collections.Generic;
using UnityEngine;

namespace GameCore
{
    public static class TerrainArt
    {
        public const int Px = 16;
        private static bool _loaded;
        private static Color32[] _atlas;
        private static int _atlasW, _atlasH;
        private static readonly Dictionary<string, List<int>> _looks = new Dictionary<string, List<int>>();

        private static readonly Color32 Outline = new Color32(0x14, 0x16, 0x17, 255);

        // Looks that join up into continuous walls: edges facing anything else get an outline,
        // and the top edge gets a lighter "wall top" band.
        private static readonly HashSet<string> Connecting = new HashSet<string> { "wall", "plaster", "concrete", "cliff", "hull", "plank", "window", "foliage", "redfoliage", "junk" };
        // Tall things cast a drop shadow down-right.
        private static readonly HashSet<string> NoShadow = new HashSet<string>
        {
            "bush", "fence", "fence_v", "fence_torn", "debris", "reeds", "rubble", "brush", "door_open", "door_broken",
            "campfire", "stones", "barrierpole", "platform", "culvert", "hatch", "bones", "rail", "rail_v", "roadline", "logs", "trench",
        };

        private static void Load()
        {
            if (_loaded) return;
            _loaded = true;
            var png = Resources.Load<TextAsset>("Sprites/terrain_atlas");
            var names = Resources.Load<TextAsset>("Sprites/terrain_names");
            if (png == null || names == null) return;
            var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            if (!tex.LoadImage(png.bytes)) return;
            _atlas = tex.GetPixels32();
            _atlasW = tex.width;
            _atlasH = tex.height;
            Object.Destroy(tex);
            var lines = names.text.Split('\n');
            for (int i = 0; i < lines.Length; i++)
            {
                string n = lines[i].Trim();
                if (n.Length == 0) continue;
                int hash = n.IndexOf('#');
                string look = hash >= 0 ? n.Substring(0, hash) : n;
                if (!_looks.TryGetValue(look, out var list)) _looks[look] = list = new List<int>();
                list.Add(i);
            }
        }

        /// <summary>Atlas cell for a look at a tile (variant chosen by position), or -1.</summary>
        private static int Cell(string look, int x, int y, bool coarse = false)
        {
            if (look == null || !_looks.TryGetValue(look, out var list)) return -1;
            // coarse: neighbouring tiles of one object (a container row, a car) share a variant
            return list[(int)(ZoneThemes.Hash01(coarse ? x / 4 : x, coarse ? y / 4 : y, 7) * list.Count) % list.Count];
        }

        private static Color32 CellPx(int cell, int px, int py) // py counted from the cell's top
        {
            int cols = _atlasW / Px;
            int ax = (cell % cols) * Px + px;
            int ay = _atlasH - 1 - ((cell / cols) * Px + py);
            return _atlas[ay * _atlasW + ax];
        }

        // coarse = neighbouring tiles usually agree (solids); fine = every tile rolls its own (cover)
        private static string Pick(string[] options, int x, int y, bool coarse = true) =>
            options == null || options.Length == 0 ? null
            : options[(int)(ZoneThemes.Hash01(coarse ? x / 4 : x, coarse ? y / 4 : y, 3) * options.Length) % options.Length];

        /// <summary>What stands on a tile, as a look name (null = bare floor).</summary>
        public static string ObjectLook(int x, int y, ZoneTheme theme)
        {
            var t = TerrainMap.GetTile(x, y);
            switch (t.Type)
            {
                case TileType.Solid:
                    if (t.Look != null) return t.Look;
                    if (x <= 1 || y <= 1 || x >= TerrainMap.Width - 2 || y >= TerrainMap.Height - 2) return theme.Border;
                    int solidNeighbours = (Solid(x - 1, y) ? 1 : 0) + (Solid(x + 1, y) ? 1 : 0) + (Solid(x, y - 1) ? 1 : 0) + (Solid(x, y + 1) ? 1 : 0);
                    return solidNeighbours >= 2 ? theme.Mass : Pick(theme.Props, x, y);
                case TileType.ScatterCover:
                    if (t.Look == "fence" && (Is(x, y - 1, "fence") || Is(x, y + 1, "fence")) && !Is(x - 1, y, "fence") && !Is(x + 1, y, "fence"))
                        return "fence_v";
                    return t.Look ?? Pick(theme.Cover, x, y, coarse: false);
                case TileType.HardCover: return t.Look ?? Pick(theme.Hard, x, y, coarse: false);
                case TileType.Door: return t.Look == "metal" ? "metaldoor" : "door";
                case TileType.DoorOpen: return t.Look == "broken" ? "door_broken" : "door_open";
                case TileType.Barrel: return "barrel";
                case TileType.Difficult:
                    if (t.Look != null) return t.Look;
                    return t.Ground == GroundType.Water || t.Ground == GroundType.Mud ? null : "rubble";
                default: return t.Look;
            }
        }

        private static bool Solid(int x, int y) => TerrainMap.GetTile(x, y).Type == TileType.Solid;

        private static bool Is(int x, int y, string look) =>
            x >= 0 && y >= 0 && x < TerrainMap.Width && y < TerrainMap.Height && TerrainMap.GetTile(x, y).Look == look;

        private static bool IsWallish(int x, int y, ZoneTheme theme)
        {
            if (x < 0 || y < 0 || x >= TerrainMap.Width || y >= TerrainMap.Height) return true;
            var t = TerrainMap.GetTile(x, y);
            if (t.Type == TileType.Door || t.Type == TileType.DoorOpen) return true;
            return t.Type == TileType.Solid && Connecting.Contains(ObjectLook(x, y, theme));
        }

        // Per-zone caches, rebuilt by Compose.
        private static int[] _objCell, _groundCell;
        private static bool[] _casts, _connects;

        /// <summary>Builds the whole map's pixels (row 0 = bottom of the texture, Unity's order).</summary>
        public static Color32[] Compose(string zoneId)
        {
            Load();
            int w = TerrainMap.Width, h = TerrainMap.Height;
            var theme = ZoneThemes.For(zoneId);
            _objCell = new int[w * h];
            _groundCell = new int[w * h];
            _casts = new bool[w * h];
            _connects = new bool[w * h];
            for (int y = 0; y < h; y++)
                for (int x = 0; x < w; x++)
                    ResolveTile(x, y, theme);
            var px = new Color32[w * Px * h * Px];
            for (int y = 0; y < h; y++)
                for (int x = 0; x < w; x++)
                    DrawTile(px, x, y, theme);
            return px;
        }

        /// <summary>Re-resolves and redraws the tiles around a changed one (its own art, the
        /// neighbours' wall edges, and the shadows it casts down-right).</summary>
        public static void Recompose(Color32[] px, string zoneId, int cx, int cy)
        {
            if (_objCell == null || px == null) return;
            var theme = ZoneThemes.For(zoneId);
            for (int y = cy - 1; y <= cy + 1; y++)
                for (int x = cx - 1; x <= cx + 1; x++)
                    if (x >= 0 && y >= 0 && x < TerrainMap.Width && y < TerrainMap.Height) ResolveTile(x, y, theme);
            for (int y = cy - 1; y <= cy + 2; y++)
                for (int x = cx - 1; x <= cx + 2; x++)
                    if (x >= 0 && y >= 0 && x < TerrainMap.Width && y < TerrainMap.Height) DrawTile(px, x, y, theme);
        }

        private static void ResolveTile(int x, int y, ZoneTheme theme)
        {
            int i = y * TerrainMap.Width + x;
            var t = TerrainMap.GetTile(x, y);
            string look = ObjectLook(x, y, theme);
            _objCell[i] = _atlas == null ? -1 : Cell(look, x, y, t.Type == TileType.Solid);
            _groundCell[i] = _atlas == null ? -1 : Cell("g_" + t.Ground.ToString().ToLowerInvariant(), x, y);
            _casts[i] = look != null && !NoShadow.Contains(look) && t.Type != TileType.Empty;
            _connects[i] = t.Type == TileType.Solid && look != null && Connecting.Contains(look);
        }

        private static void DrawTile(Color32[] px, int x, int y, ZoneTheme theme)
        {
            int w = TerrainMap.Width, h = TerrainMap.Height, texW = w * Px;
            int i = y * w + x;
            var tile = TerrainMap.GetTile(x, y);
            int ground = _groundCell[i], obj = _objCell[i];
            Color32 flat = FlatColor(tile);
            int crack = -1;
            int max = TileRules.MaxIntegrity(tile);
            if (tile.Damage > 0 && max > 0 && _looks.TryGetValue("fx_crack", out var cracks))
                crack = cracks[tile.Damage * 2 >= max ? cracks.Count - 1 : 0];

            bool connects = _connects[i];
            bool wallN = false, wallS = false, wallW = false, wallE = false;
            if (connects)
            {
                wallN = IsWallish(x, y - 1, theme); wallS = IsWallish(x, y + 1, theme);
                wallW = IsWallish(x - 1, y, theme); wallE = IsWallish(x + 1, y, theme);
            }
            float shade = Mathf.Clamp(tile.Height * 0.025f, -0.12f, 0.15f);

            for (int py = 0; py < Px; py++)
                for (int pxl = 0; pxl < Px; pxl++)
                {
                    Color32 c = ground >= 0 ? CellPx(ground, pxl, py) : flat;
                    if (ground >= 0)
                    {
                        // soften the hard line between two floor types: within 3px of an edge,
                        // some pixels come from the neighbour's floor instead
                        int edge = System.Math.Min(System.Math.Min(pxl, Px - 1 - pxl), System.Math.Min(py, Px - 1 - py));
                        if (edge < 3)
                        {
                            int nx = pxl == edge ? x - 1 : Px - 1 - pxl == edge ? x + 1 : x;
                            int ny = nx != x ? y : (py == edge ? y - 1 : y + 1);
                            if (nx >= 0 && ny >= 0 && nx < w && ny < h)
                            {
                                int ng = _groundCell[ny * w + nx];
                                if (ng >= 0 && TerrainMap.GetTile(nx, ny).Ground != tile.Ground
                                    && ZoneThemes.Hash01(x * Px + pxl, y * Px + py, 11) < (3 - edge) * 0.22f)
                                    c = CellPx(ng, pxl, py);
                            }
                        }
                    }

                    // drop shadow from whatever sits 3px up-left (possibly a neighbouring tile)
                    int gx = x * Px + pxl - 3, gy = y * Px + py - 3;
                    if (gx >= 0 && gy >= 0)
                    {
                        int sx = gx / Px, sy = gy / Px, si = sy * w + sx;
                        if (_casts[si] && (_objCell[si] < 0 || CellPx(_objCell[si], gx % Px, gy % Px).a > 0))
                            c = Mul(c, 0.68f);
                    }

                    if (obj >= 0) c = Over(c, CellPx(obj, pxl, py));
                    else if (_atlas == null && tile.Type != TileType.Empty) c = flat;

                    if (connects)
                    {
                        if (!wallN && py <= 2) c = Lerp(c, new Color32(255, 255, 255, 255), py == 0 ? 0f : 0.18f);
                        if ((!wallN && py == 0) || (!wallS && py == Px - 1) || (!wallW && pxl == 0) || (!wallE && pxl == Px - 1)) c = Outline;
                    }
                    if (crack >= 0) c = Over(c, CellPx(crack, pxl, py));
                    if (shade != 0f) c = Lerp(c, shade > 0 ? new Color32(255, 255, 255, 255) : new Color32(0, 0, 0, 255), Mathf.Abs(shade));

                    int ty = (h - 1 - y) * Px + (Px - 1 - py);
                    px[ty * texW + x * Px + pxl] = c;
                }
        }

        private static Color32 FlatColor(TerrainTile t)
        {
            switch (t.Type)
            {
                case TileType.Solid: return new Color32(38, 38, 38, 255);
                case TileType.ScatterCover: return new Color32(89, 77, 38, 255);
                case TileType.HardCover: return new Color32(110, 110, 100, 255);
                case TileType.Difficult: return new Color32(70, 62, 48, 255);
                case TileType.Door: return new Color32(90, 62, 38, 255);
                case TileType.Barrel: return new Color32(154, 42, 30, 255);
                default: return new Color32(56, 56, 56, 255);
            }
        }

        private static Color32 Over(Color32 dst, Color32 src)
        {
            if (src.a == 0) return dst;
            if (src.a == 255) return src;
            float a = src.a / 255f;
            return new Color32((byte)(src.r * a + dst.r * (1 - a)), (byte)(src.g * a + dst.g * (1 - a)), (byte)(src.b * a + dst.b * (1 - a)), 255);
        }

        private static Color32 Mul(Color32 c, float f) => new Color32((byte)(c.r * f), (byte)(c.g * f), (byte)(c.b * f), 255);

        private static Color32 Lerp(Color32 a, Color32 b, float t) =>
            new Color32((byte)(a.r + (b.r - a.r) * t), (byte)(a.g + (b.g - a.g) * t), (byte)(a.b + (b.b - a.b) * t), 255);
    }
}
